import itertools
import json

def solve_puzzle():
    # Attributes
    houses = [1, 2, 3, 4]  # left to right
    names = ['Arnold', 'Peter', 'Eric', 'Alice']
    styles = ['craftsman', 'colonial', 'victorian', 'ranch']
    hair_colors = ['red', 'blonde', 'black', 'brown']
    children = ['Bella', 'Fred', 'Meredith', 'Samantha']
    genres = ['mystery', 'fantasy', 'romance', 'science fiction']

    # Helper to build result dictionary
    def build_result(name_by_house, style_by_house, hair_by_house, child_by_house, genre_by_house):
        header = ["House", "name", "style of house", "hair colors", "child", "favorite book genres"]
        rows = []
        for i in range(4):
            rows.append([
                str(i + 1),
                name_by_house[i],
                style_by_house[i],
                hair_by_house[i],
                child_by_house[i],
                genre_by_house[i],
            ])
        return {"solution": {"header": header, "rows": rows}}

    # Iterate with pruning
    for style_by_house in itertools.permutations(styles):
        # 1. The person in a Craftsman-style house is in the third house.
        if style_by_house[2] != 'craftsman':
            continue

        for hair_by_house in itertools.permutations(hair_colors):
            # 9. The person who has black hair is in the second house.
            if hair_by_house[1] != 'black':
                continue
            # 3. The person who has brown hair is in the fourth house.
            if hair_by_house[3] != 'brown':
                continue

            # 5. The person in a ranch-style home is somewhere to the right of the person who has red hair.
            if style_by_house.index('ranch') <= hair_by_house.index('red'):
                continue

            for name_by_house in itertools.permutations(names):
                # 12. The person who has black hair is Eric.
                if name_by_house[hair_by_house.index('black')] != 'Eric':
                    continue
                # 7. Arnold is the person who has red hair.
                if name_by_house[hair_by_house.index('red')] != 'Arnold':
                    continue
                # 8. Alice is the person living in a colonial-style house.
                if name_by_house[style_by_house.index('colonial')] != 'Alice':
                    continue

                for child_by_house in itertools.permutations(children):
                    # 4. The person's child is named Samantha is in the fourth house.
                    if child_by_house[3] != 'Samantha':
                        continue
                    # 6. Peter is the person's child is named Bella.
                    if child_by_house[name_by_house.index('Peter')] != 'Bella':
                        continue
                    # 11. Arnold is the person's child is named Meredith.
                    if child_by_house[name_by_house.index('Arnold')] != 'Meredith':
                        continue

                    for genre_by_house in itertools.permutations(genres):
                        # 10. The person who loves fantasy books is Peter.
                        if genre_by_house[name_by_house.index('Peter')] != 'fantasy':
                            continue
                        # 2. Alice is the person who loves romance books.
                        if genre_by_house[name_by_house.index('Alice')] != 'romance':
                            continue
                        # 13. The person who loves science fiction books is Arnold.
                        if genre_by_house[name_by_house.index('Arnold')] != 'science fiction':
                            continue

                        # All constraints satisfied; build and return result
                        return build_result(name_by_house, style_by_house, hair_by_house, child_by_house, genre_by_house)

    raise ValueError("No solution found")

if __name__ == "__main__":
    solution = solve_puzzle()
    print(json.dumps(solution, ensure_ascii=False, indent=2))
